import java.math.*;
import java.util.*;
import java.util.Map.Entry;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DefaultDeserializationContext_findObjectId_TriageGen0Test {

    private StdDeserializationContext context;
    private ObjectIdGenerator<?> mockGen;
    private ObjectIdResolver mockResolverType;
    private ObjectIdResolver mockExistingResolver;

    @Before
    public void setUp() {
        // Using StdDeserializationContext as it's a concrete implementation of DefaultDeserializationContext
        context = mock(StdDeserializationContext.class);
        // We need a real or spy context because the method accesses internal fields _objectIds and _objectIdResolvers
        // Since these are protected/package-private, we use a real instance via a subclass or mock behavior if possible.
        // However, since we want to test the logic of the method itself, we must use a real instance.
        // Because the constructor is protected, we can use a subclass or StdDeserializationContext.

        // We'll use a spy on a real instance to allow the method to execute its logic on internal state.
        context = spy(new StdDeserializationContext(null, null));

        mockGen = mock(ObjectIdGenerator.class);
        mockResolverType = mock(ObjectIdResolver.class);
        mockExistingResolver = mock(ObjectIdResolver.class);
    }

    @Test
    public void testFindObjectId_FirstTime_CreatesNewEntry() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);

        when(mockGen.key(id)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId result = context.findObjectId(id, mockGen, mockResolverType);

        assertNotNull(result);
        assertEquals(key, result.getObjectId());
        verify(mockGen).key(id);
        verify(mockResolverType).newForDeserialization(context);
    }

    @Test
    public void testFindObjectId_ExistingId_ReturnsSameEntry() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);

        when(mockGen.key(id)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        // First call
        ReadableObjectId firstResult = context.findObjectId(id, mockGen, mockResolverType);
        // Second call
        ReadableObjectId secondResult = context.findObjectId(id, mockGen, mockResolverType);

        assertSame(firstResult, secondResult);
        // Verify resolver was only created once
        verify(mockResolverType, times(1)).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_WithNullId() {
        Object id = null;
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);

        when(mockGen.key(null)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId result = context.findObjectId(null, mockGen, mockResolverType);

        assertNotNull(result);
        assertEquals(key, result.getObjectId());
    }

    @Test
    public void testFindObjectId_UsesExistingCompatibleResolver() {
        Object id1 = "id1";
        Object id2 = "id2";
        ObjectIdGenerator.IdKey key1 = mock(ObjectIdGenerator.IdKey.class);
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);

        when(mockGen.key(id1)).thenReturn(key1);
        when(mockGen.key(id2)).thenReturn(key2);

        // Setup first resolver
        when(mockResolverType.newForDeserialization(any())).thenReturn(mockExistingResolver);
        when(mockExistingResolver.canUseFor(mockResolverType)).thenReturn(true);

        // First call: creates resolver via resolverType
        context.findObjectId(id1, mockGen, mockResolverType);

        // Second call with a different resolver type that is compatible with the existing one
        ObjectIdResolver secondResolverType = mock(ObjectIdResolver.class);
        when(mockExistingResolver.canUseFor(secondResolverType)).thenReturn(true);

        ReadableObjectId result2 = context.findObjectId(id2, mockGen, secondResolverType);

        assertNotNull(result2);
        // Verify it didn't call newForDeserialization for the second ID because it reused the resolver
        verify(mockResolverType, times(1)).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_NewResolverWhenExistingIsNoMatch() {
        Object id1 = "id1";
        Object id2 = "id2";
        ObjectIdGenerator.IdKey key1 = mock(ObjectIdGenerator.IdKey.class);
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);

        when(mockGen.key(id1)).thenReturn(key1);
        when(mockGen.key(id2)).thenReturn(key2);

        // First call: resolver A
        ObjectIdResolver resolverA = mock(ObjectIdResolver.class);
        when(mockResolverType.newForDeserialization(any())).thenReturn(resolverA);
        when(resolverA.canUseFor(any())).thenReturn(false); // Not compatible with anything else

        context.findObjectId(id1, mockGen, mockResolverType);

        // Second call: different resolver type
        ObjectIdResolver resolverBType = mock(ObjectIdResolver.class);
        ObjectIdResolver resolverB = mock(ObjectIdResolver.class);
        when(resolverBType.newForDeserialization(any())).thenReturn(resolverB);
        when(resolverA.canUseFor(resolverBType)).thenReturn(false);

        ReadableObjectId result2 = context.findObjectId(id2, mockGen, resolverBType);

        assertNotNull(result2);
        // Verify both resolver types were used to create resolvers
        verify(mockResolverType, times(1)).newForDeserialization(any());
        verify(resolverBType, times(1)).newForDeserialization(any());
    }
}
